} // setupLogging


/**
 * Setup the bot configuration from a set of environment variables and command line parameters.
 * @param {object} [options] - Command line options
 * @param {boolean} [options. akustis] - Skip loading akustis module / connecting toacoustic server
 * @param {boolean} [options.debug] - Equates to --debug in command line
 * @param {string} [options.server] - HOST:PORT of acoustic server to connect to (env var: ACOUSTIC_SERVER)
 * @param {string} [options.token] - Bot API token (env var: ACOUSTIS_API_TOKEN)
 * @param {string} [options.appui] - App ID to load (env var: ACOUSTIS_APP)
 * @param {string} [options.log] - cooked log file name (env var: LOG_FILE)
 * @param {string} [options.logLevel] - Log level (env var: LOG_LEVEL)
 * @return {Promise<object>} - resolves to the final bot configuration objectут
 */
function setupConfig(options) {
    options = options || {};

    var Acoustic = require('./lib/acoustic');
    var config = {
        akustis: !!options.akustis,
        debug: options.debug || process.argv.includes('--debug'),
        server: options.server || process.env.ACOUSTIC_SERVER,
        token: options.token || process.env.ACOUSTIS_API_TOKEN,
        app: options.appui || process.env.ACOUSTIS_APP,
        logger: null,
        log: options.log || process.env.LOG_FILE,
        logLevel: options.logLevel || process.env.LOG_LEVEL
    };

    // Load Acoustis module and connect to server if needed
    if (!config.akustis) {
        Acoustic.configure({
            server: config.server,
            token: config.token,
            app: config.app
        });
    }

    return setupEnv() // load envvars
        .then(() => setupLogging(config))
        .then(logger => {
            config.logger = logger;
            if (!config.akustis) {
                // Start Acoustic connection and wait for connection (and app deployment)
                return Acoustic.connect()
                    .then(() => Acoustic.useApp(config.app))
                    .then(() => config);
            }
        });
} // setupConfig


/**
 * Execute the bot.
 * @param {object} botConfig - Bot configuration parameters (output of setupConfig)
 * @return {Promise<AnyBot>} - Promise resolving to the running Bot instance
 */
function executeBot(botConfig) {

    /*
     * Load and initialize the bot. The bot instance is attached to 'module.exports'
     * so that it can be imported elsewhere.
     */
    var Bot = require('./lib/bot');
    var bot = new Bot(botConfig);
    module.exports = bot; // expose the bot publicly for testing

    return bot.load()
        .then(() => bot); // resolve the promise once bot is loaded
} // executeBot


/**
 * Main - Setup config and run the bot
 * @param {object} options - Command line options (see setupConfig for particulars)
 * @return {Promise} - resolves once the bot is running, rejects on startup error
 */
function main(options) {
    return setupConfig(options)
        .then(executeBot)
        .then(bot => {
            bot.start();
        })
        .catch(err => {
            botConfig.logger.error('Character bot could not start:', err.stack);
            throw err; // rethrow to indicate a hard failure
        });
} // main


