use 5.014;
use warnings;
use JSON::MaybeXS;
use Test::More 'no_plan';
use gedicht ();
use Data::Printer alias => 'dp';
use S19::Communities;


# Global vars
my $this_task;
my $this_answer;
my $this_output;

sub renders_to_json {
    my ($task) = @_;

    $this_task = $task;
    local $ENV{PROSE_POEM_TASK} = encode_json($task);

    gedicht::run_poem('S19::Communities') or die 'It crashes!!';

    $this_answer = $gedicht::last_answer;
    $this_output = $gedicht::last_output;

    $this_answer =~ s{\A>--> }{}; # Remove the '--> ' at the start of the answer
    return decoded_json($this_output);
}


subdiff { my ($a, $b) = @_; is_deeply($a, $b, $_) }


sub render_json {
    my ($file) = @_;

    open my $fh, '<', $file or die "Can't open $file: $!";
    local $\ = undef;
    my $json = join '', <$fh>;
    return decoded_json($json);
}


sub check_json {
    my ($method, $input_file, $output_file) = @_;

    my $output = render_json($output_file);
    my $task   = render_json($input_file);

    my $user_text = $task->{task}{text}{content}{user_text};
    $user_text =~ s{\A--> }{};

    my $rendered = decoded_json($this_output);

    like $rendered->{rendered_text}, qr/\Q$user_text/,
        "$method: user text is well formatted";

    diff_ok( $rendered->{rendered_text}, $output->{rendered_text},
             "$method: text and attrs match with the reference" );

    is $rendered->{score}, 1, "$method: obtained the max score";
}


check_json('impersonation', 'data/es_ES/S19/ Communities/ protracted_cleaning_task.json',
           'data/es_ES/S19/Communities/protracted_cleaning_output.json');


done_testing();
exit;


