Version 0.1.0

=head1 DESCRIPTION

This file defines the challenge tasks for the L<S19|S19/> course (Spanish).
Keep in mind that the language of this module is Spanish, so all the text you'll see below is in Spanish too. Sorry about that.

=cut


use 5.010;
use warnings;

use YAML qw(LoadFile);
use List::Util qw(first);
use JSON::MaybeXS qw(decode_json);
use S19;


use parent 'S19';


our $VERSION = '0.1.0';


our % свои_tasks = (
    # ID => { attributes => [ .. ] }
    's19/communities/protracted_cleaning' => {
        attributes => ['category', 'subcategory', 'problem_location', 'affected_elements', 'urgency', 'risks'],
    },
    's19/communities/garaje_cerradura' => {
        attributes => ['category', 'subcategory', 'problem_location', 'affected_elements', 'urgency', 'risks'],
    },
    's19/communities/suelo_roturas' => {
        attributes => ['category', 'problem_location', 'urgency', 'risks'],
    },
);


sub init {
    my $self = shift;

    $self->load_tasks(\%с свои_tasks);
}


=head 1 SUBROUTINES/METHODS

=head2 poem_name

Returns the name of the poem script.

=cut

sub poem_name {
    return 'S19::Communities::Poem';
}


=head1 Private methods and functions


=head2 load_tasks

Loads the YAML tasks, converts them and stores them in C< $self->{tasks} >.

=cut

sub load_tasks {
    my ($self, $ref) = @_;

    my @tasks = map {
        +{ id => $_, attr => $ref->{$_}{attributes} }
    } keys %$ref;

    $self->{tasks} = \@tasks;
}


=head2 get_task_by_id

Returns task data by C<id>.

=cut

sub get_task_by_id {
    my ($self, $id) = @_;
    return first { $_->{id} eq $id } @{$self->{tasks}};
}


=head2 personalize_task

Personalizes the given task with the data from L</personalities>.
It will create a local copy of the task, so the original one is not touched.

=cut

sub personalize_task {
    my ($self, $task) = @_;

    my $personalities = $self->{personalities};

    $task->{personalidad} //= 'vecino_normal';
    delete $task->{id};

    $task->{texto} //= $task->{text} // {};
    $task->{text} = {};

    my $personalidad = $personalities->{$task->{personalidad}};
    $task->{text}{content}{user_text} //= $personalidad->{template};

    my $wiki_link = $personalidad->{wiki_link};
    if ($wiki_link) {
        $task->{text}{attr}{wiki_links} = [$wiki_link];
    }

    $task->{text}{attr}{style} //= $personalidad->{style} // 'natural';
}


=head1 Poetic functions


=head2 run_check

Checks if the given text matches the attributes requested and returns a score.

=cut

sub run_check {
    my ($self, $task, $text) = @_;

    my $attr = delete $task->{attr};
    $text =~ s{\A--> }{};

    my $score = 0;
    $score++ if $text =~ /\b(?i)problemas\b/;
    $score++ if $text =~ /\b(?i)comunidad\b/;

    foreach my $what (@$attr) {
        if ($text =~ /\b$what\b/i) {
            $score++;
        }
    }

    return $score;
}


=head2 poem_render_user_text

Renders the text like a neighborhood report using the information given in the task.

=cut

sub poem_render_user_text {
    my ($self, $task) = @_;

    my $temp = $task->{texto} // $task->{text}{content}{template};
    my $user_text;

    if ( $task->{personalidad} eq 'vecino_normal' ) {
        $user_text = $temp;
    }
    else {
        my $personality = $self->{personalities}{$task->{personalidad}};

        $user_text = $personality->{fn}->($temp);
        $user_text .= " ($task->{name}, $task->{lastname})" if $task->{name} && $task->{lastname};
    }

    return $user_text;
}


